#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_LINE 0x800

static char *url_decode(const char *src, char *dst) {
    const unsigned char *s = (const unsigned char *)src;
    unsigned char *d = (unsigned char *)dst;
    while (*s) {
        if (*s == '+') {
            *d++ = ' ';
            s++;
        } else if (*s == '%' && isxdigit(s[1]) && isxdigit(s[2])) {
            unsigned int hi = isdigit(s[1]) ? s[1] - '0' : (tolower(s[1]) - 'a' + 10);
            unsigned int lo = isdigit(s[2]) ? s[2] - '0' : (tolower(s[2]) - 'a' + 10);
            *d++ = (unsigned char)((hi << 4) | lo);
            s += 3;
        } else {
            *d++ = *s++;
        }
    }
    *d = '\0';
    return (char *)dst;
}

int main(void) {
    static char line[MAX_LINE];
    static char key_buf[MAX_LINE];
    static char val_buf[MAX_LINE];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }
    size_t len = strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }
    char *saveptr1;
    char *token = strtok_r(line, "&", &saveptr1);
    while (token != NULL) {
        char *eq = strchr(token, '=');
        if (eq) {
            *eq = '\0';
            url_decode(token, key_buf);
            url_decode(eq + 1, val_buf);
        } else {
            url_decode(token, key_buf);
            val_buf[0] = '\0';
        }
        printf("%s=%s\n", key_buf, val_buf);
        token = strtok_r(NULL, "&", &saveptr1);
    }
    return 0;
}
